const cmds = [
  ["guidance", "sed -n '1,260p' CLAUDE.md; sed -n '1,260p' AGENTS.md; find packages/server packages/owletto -name AGENTS.md -print", 30000],
  ["state", "git status --short --branch; git remote -v; gh pr view 2211 --json number,title,state,headRefName,headRefOid,baseRefName,baseRefOid,mergeable,files,commits,url", 30000],
  ["gotchas", "rg -n \"conversation|transcript|MCP|client_id|client|event\" docs/GOTCHAS.md | head -160", 12000]
];
const out = await Promise.all(cmds.map(async ([name, cmd, max]) => {
  const res = await tools.exec_command({cmd, workdir:"/Users/burakemre/Code/lobu", yield_time_ms:10000, max_output_tokens:max});
  return `### ${name}\n${res.output}`;
}));
out.forEach(text);

