     6	/** A conversation's origin class, mirroring how the listing partitions ids. */
     7	export type ConversationKind = "owned" | "platform";
     8	
     9	/** Watcher conversation id shape: `{agentId}_watcher_{id}_run_{runId}`. These
    10	 *  stay derived from `agent_transcript_snapshot` (one sidebar entry per WATCHER,
    11	 *  not per run) and must NEVER get a `conversations` row. */
    12	const WATCHER_CONVERSATION_ID = /_watcher_\d+_run_\d+$/;
    13	
    14	export function isWatcherConversationId(conversationId: string): boolean {
    15		return WATCHER_CONVERSATION_ID.test(conversationId);
    16	}
    17	
    18	/**
    19	 * Derive a conversation's stored (kind, platform) from the EXPLICIT dispatch
    20	 * platform — never by parsing the id string. The app's own threads dispatch with
    21	 * `platform: "api"` (the marker the whole gateway already gates on, e.g.
    22	 * interactions.ts:57, unified-thread-consumer.ts:391) and are stored as
    23	 * ('owned', 'web'); every other platform is a real external channel stored as
    24	 * ('platform', <platform>). Returning both from one place keeps kind and the
    25	 * stored platform from drifting apart at the call site. Watcher ids are filtered
    26	 * out BEFORE this by {@link isWatcherConversationId}.
    27	 */
    28	export function classifyConversation(platform: string): {
    29		kind: ConversationKind;
    30		storedPlatform: string;
    31	} {
    32		// Lowercase-canonicalize the stored platform. platform is part of the
    33		// conversations PK, so a connector that ever emitted, say, 'Slack' would
    34		// otherwise land a duplicate row alongside a 'slack' one.
    35		const p = platform.toLowerCase();
    36		return p === "api"
    37			? { kind: "owned", storedPlatform: "web" }
    38			: { kind: "platform", storedPlatform: p };
    39	}
    40	
    41	export interface ConversationUpsert {
    42		organizationId: string;
    43		agentId: string;
    44		platform: string;
    45		conversationId: string;
    46		/**
    47		 * Web route segment for an owned conversation. Platform conversations and
    48		 * owned ids without a web thread suffix store null.
    49		 */
    50		threadId: string | null;
    51		kind: ConversationKind;
    52		userId?: string | null;
    53		title?: string | null;
    54		lastActivityAt: Date;
    55	}
    56	
    57	/**
    58	 * Materialize (or refresh) the `conversations` row for a turn. Called on every
    59	 * dispatch that starts a turn — the row is the single listing source. Idempotent:
    60	 * the first turn INSERTs, later turns bump `last_activity_at` and fill in a
    61	 * newly-known `title`/`user_id`/`thread_id` without clobbering earlier non-null
    62	 * values.
    63	 * Failures are swallowed — a listing-materialization hiccup must never fail a
    64	 * live turn.
    65	 */
    66	export async function upsertConversation(
    67		row: ConversationUpsert,
    68	): Promise<void> {
    69		// getDb() inside the try: it throws when DATABASE_URL is unset (or the pool
    70		// can't init), and a listing-materialization hiccup must never fail a live
    71		// turn — so the swallow below must cover the client acquisition too, not just
    72		// the query.
    73		try {
    74			const sql = getDb();
    75			await sql`
    76	      INSERT INTO public.conversations (
    77	        organization_id, agent_id, platform, conversation_id, thread_id,
    78	        kind, user_id, title, last_activity_at
    79	      ) VALUES (
    80	        ${row.organizationId}, ${row.agentId}, ${row.platform},
    81	        ${row.conversationId}, ${row.threadId}, ${row.kind},
    82	        ${row.userId ?? null}, ${row.title ?? null}, ${row.lastActivityAt}
    83	      )
    84	      ON CONFLICT (organization_id, agent_id, platform, conversation_id)
    85	      DO UPDATE SET
    86	        last_activity_at = GREATEST(
    87	          public.conversations.last_activity_at, EXCLUDED.last_activity_at
    88	        ),
    89	        -- keep the earliest known non-null title/user/thread; don't clobber with null
    90	        title = COALESCE(public.conversations.title, EXCLUDED.title),
    91	        user_id = COALESCE(public.conversations.user_id, EXCLUDED.user_id),
    92	        thread_id = COALESCE(public.conversations.thread_id, EXCLUDED.thread_id),
    93	        updated_at = now()
    94	    `;
    95		} catch (err) {
    96			logger.warn(
    97				{
    98					err,
    99					organizationId: row.organizationId,
   100					agentId: row.agentId,
   101					conversationId: row.conversationId,
   102				},
