    66	/**
    67	 * Which channels may THIS requester read for THIS agent — the per-agent channel
    68	 * fence (the agent's bound channels) INTERSECTED with the per-user channel ACL
    69	 * gate ({@link filterChannelsForRequester}), team-scoped. A platform conversation
    70	 * is visible iff {@link isConversationVisible}. Mirrors recall's gate so a user
    71	 * never sees a channel transcript they're not a member of.
    72	 */
    73	export async function resolveChannelVisibility(
    74		sql: DbClient,
    75		args: {
    76			organizationId: string;
    77			agentId: string;
    78			userId: string | null;
    79			allowNotGraphed?: boolean;
    80		},
    81	): Promise<ChannelVisibility> {
    82		const bound = await resolveBoundChannelRows(sql, {
    83			organizationId: args.organizationId,
    84			agentId: args.agentId,
    85		});
    86		const channelTeams = new Map<string, Set<string>>();
    87		for (const c of bound) {
    88			const bare = stripPlatformPrefix(c.platform, c.channel_id);
    89			const pc = `${c.platform.toLowerCase()}:${bare}`;
    90			const set = channelTeams.get(pc) ?? new Set<string>();
    91			set.add(c.team_id ?? "");
    92			channelTeams.set(pc, set);
    93		}
    94		const visible = await filterChannelsForRequester(sql, {
    95			organizationId: args.organizationId,
    96			userId: args.userId,
    97			rows: bound,
    98			allowNotGraphed: args.allowNotGraphed,
    99		});
   100		const visibleKeys = new Set(
   101			visible.map((c) =>
   102				channelVisibilityKey(
   103					c.platform,
   104					c.team_id,
   105					stripPlatformPrefix(c.platform, c.channel_id),
   106				),
   107			),
   108		);
   109		return { visibleKeys, channelTeams };
   110	}
