   112	/** Can the requester read this platform conversation (`{platform}:{channel}:{thread}`)?
   113	 *  Fail-closed: unbound, or a channel bound in ≥2 DISTINCT REAL workspaces (can't
   114	 *  tie the conversation to a single team), is not visible.
   115	 *
   116	 *  A NULL/"" team is a WILDCARD ("workspace unknown yet" — a binding written
   117	 *  before its workspace healed from the first inbound event), NOT a distinct
   118	 *  workspace. `team_id` is now guaranteed to be a real workspace or NULL (never a
   119	 *  Grid enterprise id), so the gate needs zero connector knowledge: it counts
   120	 *  distinct non-null teams and only fails closed on genuine cross-workspace
   121	 *  ambiguity (2+ real teams). One real team + any number of NULLs resolves to
   122	 *  that team; all-NULL resolves via the wildcard visible key. */
   123	export function isConversationVisible(
   124		conversationId: string,
   125		vis: ChannelVisibility,
   126	): boolean {
   127		const parts = conversationId.split(":");
   128		const platform = (parts[0] ?? "").toLowerCase();
   129		const channel = parts[1] ?? "";
   130		const teams = vis.channelTeams.get(`${platform}:${channel}`);
   131		if (!teams || teams.size === 0) return false; // unbound
   132		const realTeams = [...teams].filter((t) => t !== "");
   133		if (realTeams.length > 1) return false; // genuine cross-workspace ambiguity
   134		// One real team (NULLs are wildcards that resolve to it), or all-NULL (a
   135		// teamless/unknown-yet binding — resolves via the "" wildcard visible key).
   136		const team = realTeams[0] ?? null;
   137		return vis.visibleKeys.has(channelVisibilityKey(platform, team, channel));
   138	}
