   202			const oauthClientsStore = new OAuthClientsStore(sql);
   203			const oauthClients =
   204				await oauthClientsStore.listClientsByOrganization(organizationId);
   205	
   206			const referencedAgentIds = new Set<string>();
   207			for (const client of oauthClients) {
   208				const metadata = asRecord(client.metadata);
   209				const lastAgentId =
   210					typeof metadata?.last_agent_id === "string"
   211						? metadata.last_agent_id
   212						: null;
   213				if (lastAgentId) referencedAgentIds.add(lastAgentId);
   214			}
   215	
   216			const agentNames = new Map<string, string>();
   217			if (referencedAgentIds.size > 0) {
   218				const rows = await sql`
   219	        SELECT id, name
   220	        FROM agents
   221	        WHERE organization_id = ${organizationId}
   222	          AND id = ANY(${pgTextArray([...referencedAgentIds])}::text[])
   223	      `;
   224				for (const row of rows as Array<{ id: string; name: string }>) {
   225					agentNames.set(row.id, row.name);
   226				}
   227			}
   228	
   229			const mcpClients = oauthClients
   230				.map((client) => {
   231					const metadata = asRecord(client.metadata);
   232					const clientInfo = asRecord(metadata?.last_client_info);
   233					const capabilities = asRecord(metadata?.last_capabilities);
