   238						typeof metadata?.last_agent_id === "string"
   239							? metadata.last_agent_id
   240							: null;
   241	
   242					if (agentId && assignedAgentId !== agentId) return null;
   243	
   244					const title =
   245						asNonEmptyString(clientInfo?.name) ||
   246						asNonEmptyString(client.client_name);
   247					const softwareId = asNonEmptyString(client.software_id);
   248	
   249					return {
   250						id: client.client_id,
   251						kind: "mcp" as const,
   252						title,
   253						identifier: client.client_id,
   254						platform: softwareId,
   255						assignedAgentId,
   256						assignedAgentName: assignedAgentId
   257							? (agentNames.get(assignedAgentId) ?? assignedAgentId)
   258							: null,
   259						status: client.active_token_count > 0 ? "connected" : "disconnected",
   260						authState: client.active_token_count > 0 ? "authorized" : "revoked",
   261						lastSeenAt,
   262						userAgent:
   263							typeof metadata?.last_user_agent === "string"
   264								? metadata.last_user_agent
