   328	      WHERE e.organization_id = ${organizationId}
   329	        AND e.semantic_type = 'audit'
   330	        AND e.client_id IS NOT NULL
   331	        AND oc.client_name IS NOT NULL
   332	        AND oc.user_id = ${userId}
   333	        AND oc.organization_id = ${organizationId}
   334	      GROUP BY oc.client_name
   335	    `;
