529	export function useRecentAgentThreads(
530		orgSlug?: string | null,
531		agentIds?: string[],
532		options?: { enabled?: boolean; limit?: number },
533	) {
534		const limit = options?.limit ?? 8;
535		const enabled =
536			!!orgSlug && (agentIds?.length ?? 0) > 0 && (options?.enabled ?? true);
537	
538		const queries = useQueries({
539			queries: (agentIds ?? []).map((agentId) => ({
540				...agentThreadsQueryOptions(orgSlug, agentId, {
541					strict: false,
542					scope: "all",
543				}),
544				enabled,
545			})),
546		});
547	
548		const isLoading = enabled && queries.some((q) => q.isLoading);
549		const threads = queries
550			.flatMap((q, index) => {
551				const agentId = agentIds?.[index];
552				if (!agentId) return [];
553				return (q.data ?? []).map((thread) => ({
554					agentId,
555					...thread,
556				}));
557			})
558			.sort((a, b) => b.updatedAt - a.updatedAt)
559			.slice(0, limit);
560	
561		return { threads, isLoading };
562	}
